    for r in bypat[pid]:
        t=r['resourceType']; tm=(et(r) or '')[:16]
        if t=='EpisodeOfCare': continue
        if t=='Observation':
            sp=spec.get(r['specimen']['reference'].split('/')[-1]) if r.get('specimen') else None
            accn=r['identifier'][0]['value'] if r.get('identifier') else None
            bs=acc_basic.get(accn,[])
            lbl='' ; ok=True
            if sp:
                sm,sd,sn=ext(sp,'label-mrn'),str(ext(sp,'label-dob')),ext(sp,'label-name')
                if (sm,sd)!=(mrn(pt),pt['birthDate']) or sn.split(',')[0].strip().lower()!=pt['name'][0]['text'].split()[-1].lower():
                    lbl+=' SPEC-LABEL[%s|%s|%s]'%(sn,sm,sd)
            for b in bs:
                bm,bd,bn=ext(b,'patient-mrn'),str(ext(b,'patient-dob')),ext(b,'patient-name')
                if (bm,bd)!=(mrn(pt),pt['birthDate']) or bn.split(',')[0].strip().lower()!=pt['name'][0]['text'].split()[-1].lower():
                    lbl+=' ACC[%s|%s|%s auth=%s id=%s]'%(bn,bm,bd,b['author']['display'],b['id'])
            note=' NOTE:'+'; '.join(n['text'] for n in r.get('note',[])) if r.get('note') else ''
            print('  %s OBS %s %s = %s [%s] coll=%s acc=%s spec=%s%s%s'%(tm,r['id'],r['code']['text'],r.get('valueString'),r['status'],(r.get('effectiveDateTime') or '')[:16],accn,sp['id'] if sp else None,note,lbl))
        elif t=='Specimen':
            pass
        elif t=='DocumentReference':
            print('  %s DOC %s [%s / %s] %s'%(tm,r['id'],r['type']['text'],ext(r,'author-role'),r['author'][0]['display'] if r.get('author') else ''))
            for ln in r['description'].split('\n'):
                if ln.strip(): print('      | '+ln.strip())
        elif t=='MedicationAdministration':
            print('  %s MED %s %s | %s | %s | %s | %s'%(tm,r['id'],r['medicationCodeableConcept']['text'],r['dosage']['text'],r['status'],r['performer'][0]['actor']['display'] if r.get('performer') else '', '; '.join(n['text'] for n in r.get('note',[]))))
        elif t=='MedicationDispense':
            print('  %s DISP %s %s | q%s | %sd | %s | %s'%(tm,r['id'],r['medicationCodeableConcept']['text'],r['quantity']['value'],r['daysSupply']['value'],r['dosageInstruction'][0]['text'],'; '.join(n['text'] for n in r.get('note',[]))))
        elif t=='Condition':
            print('  %s COND %s %s (rec %s by %s)'%(tm,r['id'],r['code']['text'],r.get('recordedDate','')[:10],r.get('recorder',{}).get('display')))
        elif t=='AllergyIntolerance':
            print('  %s ALLERGY %s %s %s'%(tm,r['id'],r['code']['text'],json.dumps(r.get('reaction',''))[:200]))
        else:
            print('  %s %s %s'%(tm,t,json.dumps(r)[:300]))
    # tasks
    for tk in tasks:
        if tk.get('for',{}).get('reference','').endswith(pid) and tk['status']=='requested':
            print('  *** REQUEST',tk['id'],tk['code']['coding'][0]['code'],tk['focus']['reference'],tk['description'])
if __name__=='__main__':
    for pid in sys.argv[1:]: show(pid)
