exec(open('/tmp/load.py').read())
import datetime,re
def D(s): return datetime.date.fromisoformat(s[:10])
EV=datetime.date(2026,9,24)
def addmonths(d,m):
    y=d.year+(d.month-1+m)//12; mo=(d.month-1+m)%12+1
    day=min(d.day,[31,29 if y%4==0 and (y%100!=0 or y%400==0) else 28,31,30,31,30,31,31,30,31,30,31][mo-1])
    return datetime.date(y,mo,day)
results={}
for pid,pt in pats.items():
    ep=epsby[pid][0]
    dx=D(ep['period']['start'])
    recs=bypat[pid]
    cond=[c for c in recs if c['resourceType']=='Condition']
    stage=cond[0]['code']['text'] if cond else '??'
    stages=[c['code']['text'] for c in cond]
    doses=[]
    for m in recs:
        if m['resourceType']=='MedicationAdministration':
            doses.append((D(m['effectiveDateTime']),m['dosage']['text'],m['status'],m['id'],m['medicationCodeableConcept']['text']))
    dsp=[(D(d['whenHandedOver']),d['medicationCodeableConcept']['text'],d['quantity']['value'],d['daysSupply']['value'],d['id'],'; '.join(n['text'] for n in d.get('note',[]))) for d in recs if d['resourceType']=='MedicationDispense']
    rprs=[]
    for o in recs:
        if o['resourceType']=='Observation' and o['code']['text']=='RPR, quantitative':
            sp=spec[o['specimen']['reference'].split('/')[-1]]
            rprs.append((D(o['effectiveDateTime']),o['status'],o.get('valueString'),o['id'],sp['id']))
    flags=[]
    # identity
    ident=[]
    for o in recs:
        if o['resourceType']!='Observation': continue
        sp=spec[o['specimen']['reference'].split('/')[-1]]
        sid=(ext(sp,'label-mrn'),str(ext(sp,'label-dob'))); cid=(mrn(pt),pt['birthDate'])
        bs=acc_basic[o['identifier'][0]['value']]
        bids=set((ext(b,'patient-mrn'),str(ext(b,'patient-dob'))) for b in bs)
        if sid!=cid or bids!={cid}:
            ident.append((o['id'],o['code']['text'],(o.get('effectiveDateTime') or '')[:10],ext(sp,'label-name'),[ext(b,'patient-name') for b in bs]))
    if ident: flags.append('IDENT')
    # treatment
    good=[d for d in doses if d[2]=='completed' and '2.4' in d[1]]
    if any(d[2]!='completed' for d in doses): flags.append('NOTDONE')
    if any('2.4' not in d[1] for d in doses if d[2]=='completed'): flags.append('DOSEAMT')
    early = stage in ('Primary syphilis','Secondary syphilis','Early latent syphilis')
    need = 1 if early else 3
    if len(good)<need: flags.append('DOSES%d/%d'%(len(good),need))
    ivs=[(good[i+1][0]-good[i][0]).days for i in range(len(good)-1)]
    if any(v>9 or v<5 for v in ivs): flags.append('IV'+str(ivs))
    if dsp: flags.append('DISP')
    if any(a for a in recs if a['resourceType']=='AllergyIntolerance'): flags.append('PCNALLERGY')
    # pregnancy signals
    preg=[]
    for o in recs:
        if o['resourceType']=='Observation' and o['code']['text'].startswith('hCG'):
            preg.append((str(D(o['effectiveDateTime'])),o['status'],o.get('valueString'),o['id']))
    pregdocs=[d for d in recs if d['resourceType']=='DocumentReference' and (d['type']['text'] in ('Prenatal visit','Postpartum visit','Prenatal intake') or re.search(r'pregnan|gravid|G\dP\d|weeks|delivery|deliver|EDD|postpartum|L&D|infant',d['description'],re.I))]
    if any(p[2] in ('Positive','Reactive') or (p[2] and p[2] not in('Negative','Not detected')) or p[1]!='final' for p in preg) or pregdocs:
        flags.append('PREGSIG')
    if any(o['status']!='final' for o in recs if o['resourceType']=='Observation'): flags.append('NONFINAL')
    # follow-up
    fu=[]
    if good:
        t0=min(d[0] for d in good)
        months=[6,12] if stage in ('Primary syphilis','Secondary syphilis') else [6,12,24]
        for m in months:
            due=addmonths(t0,m); lo=due-datetime.timedelta(30); hi=due+datetime.timedelta(30)
            if hi>=EV: continue
            hits=[r for r in rprs if lo<=r[0]<=hi]
            okhits=[r for r in hits if r[1]!='cancelled']
            fu.append((m,str(due),[(str(h[0]),h[1],h[3]) for h in hits],'OK' if okhits else 'MISS'))
        if any(f[3]=='MISS' for f in fu): flags.append('FUMISS')
    outside=[d for d in recs if d['resourceType']=='DocumentReference' and ext(d,'author-role')=='outside-facility']
    othermention=[d for d in recs if d['resourceType']=='DocumentReference' and ext(d,'author-role')!='outside-facility' and re.search(r'ED\b|outside|elsewhere|urgent care|hospital|clinic |PCP|another|Health|faxed|records|referr',d['description'],re.I)]
    if outside: flags.append('OUTREC')
    if othermention: flags.append('OUTMENTION')
    results[pid]=dict(pid=pid,name=pt['name'][0]['text'],gender=pt['gender'],dob=pt['birthDate'],ep=ep['id'],dx=str(dx),stage=stage,stages=stages,
        doses=[(str(d[0]),d[1],d[2],d[3]) for d in doses],disp=[(str(d[0]),)+d[1:] for d in dsp],rprs=[(str(r[0]),r[1],r[2],r[3]) for r in rprs],
        fu=fu,flags=flags,ident=ident,preg=preg,npregdocs=len(pregdocs),noutside=len(outside))
