import json,subprocess,datetime
def D2(s): return datetime.date.fromisoformat(s[:10])
# ---------- helpers ----------
def recs(pid,rt): return [r for r in bypat[pid] if r['resourceType']==rt]
def cond_id(pid):
    c=recs(pid,'Condition'); return c[-1]['id'] if c else None
def doses_ids(pid):
    return [(str(D2(m['effectiveDateTime'])),m['id'],m['status'],m['dosage']['text']) for m in recs(pid,'MedicationAdministration')]
def outside_ids(pid):
    return [d['id'] for d in recs(pid,'DocumentReference') if ext(d,'author-role')=='outside-facility']
def doc_find(pid,sub):
    return [d['id'] for d in recs(pid,'DocumentReference') if sub.lower() in d['description'].lower()]
def disp_ids(pid):
    return [d['id'] for d in recs(pid,'MedicationDispense')]
def allergy_ids(pid):
    return [a['id'] for a in recs(pid,'AllergyIntolerance')]
def hcg(pid):
    return [(str(D2(o['effectiveDateTime'])),o['id'],o['status'],o.get('valueString')) for o in recs(pid,'Observation') if o['code']['text'].startswith('hCG')]
def rpr(pid):
    out=[]
    for o in recs(pid,'Observation'):
        if o['code']['text']=='RPR, quantitative':
            out.append((str(D2(o['effectiveDateTime'])),o['id'],o['specimen']['reference'].split('/')[-1],o['status'],o.get('valueString')))
    return sorted(out)
def spec_basic(sid):
    s=spec[sid]; return [b['id'] for b in acc_basic[s['accessionIdentifier']['value']]]
